window.kbPageData["views/entry/k-f967adabfcf3a099"] = {"key":"entry/k-f967adabfcf3a099","state":{"route":"entry/k-f967adabfcf3a099"},"node":{"id":"k-f967adabfcf3a099","mode":"k","title":"法治思想","type":"观点与论证","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["law"],"主类":["观点与论证"],"出处性质":["理论手册"],"学科":["政治理论"],"来源主题":["新时代中国特色社会主义思想"],"资料类别":["非时政"]},"directorySummary":"2020 年 11 月 16 日至 17 日，中央全面依法治国工作会议首次提出并用“十一个坚持”\n系统阐述了习近平法治思想。即：\n（1）坚持党对全面依法治国的领导。党的领导是推进全面依法治国的根本保证。\n（2）坚持以人民为中心。全面依法治国最广泛、最深厚的基础是人民，必须坚持为了\n人民、依靠人民。\n…","sources":[{"id":"1910afb83c30fe28","label":"法治思想","topic":"新时代中国特色社会主义思想","category":"非时政","text":"2020 年 11 月 16 日至 17 日，中央全面依法治国工作会议首次提出并用“十一个坚持”\n系统阐述了习近平法治思想。即：\n（1）坚持党对全面依法治国的领导。党的领导是推进全面依法治国的根本保证。\n（2）坚持以人民为中心。全面依法治国最广泛、最深厚的基础是人民，必须坚持为了\n人民、依靠人民。\n（3）坚持中国特色社会主义法治道路。中国特色社会主义法治道路本质上是中国特色\n社会主义道路在法治领域的具体体现。\n（4）坚持依宪治国、依宪执政。党领导人民制定宪法法律，领导人民实施宪法法律，\n党自身要在宪法法律范围内活动。\n（5）坚持在法治轨道上推进国家治理体系和治理能力现代化。法治是国家治理体系和\n治理能力的重要依托。\n（6）坚持建设中国特色社会主义法治体系。中国特色社会主义法治体系是推进全面依\n法治国的总抓手。\n（7）坚持依法治国、依法执政、依法行政共同推进，法治国家、法治政府、法治社会\n一体建设。全面依法治国是一个系统工程，要整体谋划，更加注重系统性、整体性、协同性。\n（8）坚持全面推进科学立法、严格执法、公正司法、全民守法。公平正义是司法的灵\n魂和生命。\n（9）坚持统筹推进国内法治和涉外法治。\n（10）坚持建设德才兼备的高素质法治工作队伍，\n（11）坚持抓住领导干部这个“关键少数”。","source":{"doc":"3ccc56f4000d1642c2d1","first":20,"last":20,"page":20,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"law","title":"法治政府与依法行政"}],"units":{"k-f967adabfcf3a099":[]}};
